  async function startCamera(){if(!('BarcodeDetector' in window)||!navigator.mediaDevices?.getUserMedia){toast('Kamera pro QR není dostupná. Použij výběr člena nebo ruční kód.');return}stopCamera();try{const detector=new BarcodeDetector({formats:['qr_code']}),box=document.querySelector('[data-live-camera-box]'),video=box?.querySelector('video');cameraStream=await navigator.mediaDevices.getUserMedia({video:{facingMode:{ideal:'environment'}},audio:false});if(!box||!video){stopCamera();return}box.hidden=false;video.srcObject=cameraStream;await video.play();const scan=async()=>{if(!cameraStream)return;try{const codes=await detector.detect(video),value=codes[0]?.rawValue;if(value){stopCamera();await resolveQr(value);return}}catch{}cameraFrame=requestAnimationFrame(scan)};cameraFrame=requestAnimationFrame(scan)}catch(error){stopCamera();toast(error?.name==='NotAllowedError'?'Přístup ke kameře byl odmítnut.':'Kameru se nepodařilo spustit.')}}
