  async function submitJudge(form){
    const entryId=form.dataset.liveJudgeForm,contextKey=`${eventId()}|${accountId()}`,writeKey=contextKey+'|'+entryId;
    if(scoreWrites.has(writeKey))return;
    const values=judgeValues(form),submittedValue=true;
    if(submittedValue&&Object.values(values.scores).some(value=>!value))return toast('Vyber známku 1–10 u všech kritérií.');
    const buttons=form.querySelectorAll('button[type=submit]'),errorNode=form.querySelector('[data-live-judge-error]'),fingerprint=JSON.stringify({...values,submitted:submittedValue});
    judgeDrafts.set(entryId,values);scoreWrites.add(writeKey);++readSequence;stop();
    buttons.forEach(button=>button.disabled=true);if(errorNode)errorNode.textContent='';
    const current=()=>contextKey===`${eventId()}|${accountId()}`;
    let confirmed=confirmedScores.get(entryId)?.fingerprint===fingerprint;
    try{
      if(!confirmed){
        const receipt=await apiRequest(`/api/live/judge/scores/${encodeURIComponent(entryId)}`,{method:'PUT',body:{...values,submitted:submittedValue}});
        if(!current())return;
        ++readSequence;
        if(receipt?.ok!==true||receipt.entryId!==entryId)throw new Error('Neplatné potvrzení uložení.');
        confirmed=true;confirmedScores.set(entryId,{fingerprint,value:receipt});
      }
      const files=judgeFiles.get(entryId)||[];let failures=0;
      for(const item of files){
        if(!current())return;
        item.status='uploading';item.error='';renderJudgePreviews(form,entryId);
        try{await apiUpload(`/api/live/judge/entries/${encodeURIComponent(entryId)}/photos`,item.file,{method:'POST'});item.status='uploaded'}
        catch(error){item.status='error';item.error=liveError(error,'Odeslání fotografie selhalo · zkus znovu');failures++}
        if(!current())return;
        renderJudgePreviews(form,entryId);
      }
      for(let index=files.length-1;index>=0;index--)if(files[index].status==='uploaded'){releaseSelection(files[index]);files.splice(index,1)}
      if(!files.length)judgeFiles.delete(entryId);
      if(failures){if(errorNode)errorNode.textContent='Hodnocení je uložené, ale některé fotografie se neodeslaly. Zkus je odeslat znovu.';return}
      if(JSON.stringify(judgeDrafts.get(entryId))===JSON.stringify(values))judgeDrafts.delete(entryId);judgeSaved=entryId;
      const refreshed=await load();if(!current())return;
      toast(refreshed?'Hodnocení je uložené.':'Hodnocení je uložené. Přehled se nepodařilo obnovit.');
      if(!refreshed){const target=bodyRoot();if(target)target.insertAdjacentHTML('afterbegin','<p role="status">Hodnocení je uložené. Přehled se nepodařilo obnovit. <button type="button" data-admin-live-retry>Obnovit přehled</button></p>')}
    }catch(error){
      if(!current())return;
      const message=confirmed?'Hodnocení je uložené. Přehled se nepodařilo obnovit.':error.status?liveError(error,'Server hodnocení odmítl. Rozepsané údaje zůstaly zachované.'):'Výsledek uložení není potvrzený. Obnov přehled nebo bezpečně zopakuj uložení.';
      if(errorNode)errorNode.textContent=message;toast(message);
    }finally{scoreWrites.delete(writeKey);buttons.forEach(button=>button.disabled=false);if(current())schedule();}
  }
